package ro.leo.visual;
import android.content.*;import android.content.pm.*;import android.net.Uri;import android.os.Bundle;import java.io.*;import java.util.*;
/** Native destination picker. Grants read access only when the user chooses a target. */
public final class ShareHubActivity extends LeoActivity {
 private Intent payload;final ArrayList<ResolveInfo> targets=new ArrayList<ResolveInfo>();
 static void send(Context c,Uri uri,String mime,String title){try{if(uri!=null&&"file".equals(uri.getScheme()))uri=LeoFileProvider.uri(c,new File(uri.getPath()));}catch(Exception e){android.widget.Toast.makeText(c,"Fișier în afara stocării Leo",0).show();return;}c.startActivity(new Intent(c,ShareHubActivity.class).setDataAndType(uri,mime==null?"application/octet-stream":mime).putExtra("title",title));}
 static void view(Context c,Uri uri,String mime){try{if(uri!=null&&"file".equals(uri.getScheme()))uri=LeoFileProvider.uri(c,new File(uri.getPath()));}catch(Exception e){android.widget.Toast.makeText(c,"Fișier în afara stocării Leo",0).show();return;}c.startActivity(new Intent(c,ShareHubActivity.class).setDataAndType(uri,mime==null?"application/octet-stream":mime).putExtra("view",true));}
 static Uri textFile(Context c,String text)throws Exception{File dir=new File(c.getCacheDir(),"shared");if(!dir.isDirectory()&&!dir.mkdirs())throw new IOException();File[] old=dir.listFiles();if(old!=null)for(File f:old)if(f.getName().startsWith("leo-share-")&&f.lastModified()<System.currentTimeMillis()-86400000L)f.delete();File f=new File(dir,"leo-share-"+UUID.randomUUID()+".txt");BackupEngine.write(f,text.getBytes("UTF-8"));return LeoFileProvider.uri(c,f);}
 static Intent payload(Uri uri,String mime,String title,boolean view){if(uri==null||!"content".equals(uri.getScheme()))throw new IllegalArgumentException("URI de conținut necesar");Intent out=new Intent(view?Intent.ACTION_VIEW:Intent.ACTION_SEND);if(view)out.setDataAndType(uri,mime);else out.setType(mime).putExtra(Intent.EXTRA_STREAM,uri).putExtra(Intent.EXTRA_SUBJECT,title);out.setClipData(ClipData.newRawUri("Fișier ales",uri));out.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);return out;}
 protected void onCreate(Bundle b){super.onCreate(b);try{payload=payload(getIntent().getData(),getIntent().getType()==null?"application/octet-stream":getIntent().getType(),getIntent().getStringExtra("title"),getIntent().getBooleanExtra("view",false));load();}catch(RuntimeException e){notice("Fișierul nu poate fi partajat");finish();}}
 private void load(){targets.clear();HashSet<ComponentName> seen=new HashSet<ComponentName>();for(ResolveInfo r:getPackageManager().queryIntentActivities(payload,PackageManager.MATCH_DEFAULT_ONLY)){ActivityInfo a=r.activityInfo;if(a!=null&&a.exported&&a.enabled&&a.applicationInfo.enabled&&!a.packageName.equals(getPackageName())&&(a.permission==null||checkSelfPermission(a.permission)==PackageManager.PERMISSION_GRANTED)&&seen.add(new ComponentName(a.packageName,a.name)))targets.add(r);if(targets.size()>=100)break;}final java.text.Collator order=java.text.Collator.getInstance(new Locale("ro"));Collections.sort(targets,new Comparator<ResolveInfo>(){public int compare(ResolveInfo a,ResolveInfo b){return order.compare(a.loadLabel(getPackageManager()).toString(),b.loadLabel(getPackageManager()).toString());}});ArrayList<String> names=new ArrayList<String>();for(ResolveInfo r:targets)names.add(r.loadLabel(getPackageManager()).toString()+"\n"+r.activityInfo.applicationInfo.loadLabel(getPackageManager()));list(getIntent().getBooleanExtra("view",false)?"Deschide cu":"Partajează prin",names,0,new Choice(){public void pick(int n){launch(n);}},"Actualiz.",new Runnable(){public void run(){load();}});if(names.isEmpty())notice("Nicio destinație compatibilă disponibilă");}
 private void launch(int n){if(n<0||n>=targets.size())return;ActivityInfo a=targets.get(n).activityInfo;try{startActivity(new Intent(payload).setComponent(new ComponentName(a.packageName,a.name)));}catch(RuntimeException e){notice("Destinația nu poate deschide fișierul");}}
}
